def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    op = [h[1] for h in history]
    total_coop = op.count('C')
    coop_rate = total_coop / n

    # Detect consecutive defections at the end
    streak = 0
    for a in reversed(op):
        if a == 'D':
            streak += 1
        else:
            break

    # Detect if opponent is currently in a cooperation streak
    coop_streak = 0
    for a in reversed(op):
        if a == 'C':
            coop_streak += 1
        else:
            break

    last_op = op[-1]

    # Very cooperative opponent overall: cooperate, only punish long defection streaks
    if coop_rate >= 0.85:
        if last_op == 'D' and streak >= 2:
            return 'D' if streak >= 3 else 'C'
        return 'C'

    # Very defective opponent: defend
    if coop_rate <= 0.2:
        # Occasional olive branch to break mutual defection when stuck
        if streak >= 1 and n % 7 == 0:
            return 'C'
        return 'D'

    # Moderate opponent: mostly cooperative behavior with quick retaliation
    # and quick forgiveness to restore mutual cooperation.

    if last_op == 'D':
        # Punish but recover fast: if only one defection after cooperation, retaliate once
        if streak >= 3:
            return 'D'
        if streak == 1 and coop_streak >= 2:
            # isolated defection in otherwise cooperative play: punish once
            return 'D'
        if streak == 2:
            # second defection: keep punishing but prepare to forgive
            return 'D'
        # longer coop context: retaliate
        return 'D'

    # Opponent cooperated last
    if streak == 0:
        # If our last action was D and they cooperated, forgive and cooperate
        my_last = history[-1][0] if n > 0 else 'C'
        if my_last == 'D':
            return 'C'
        # Opponent is cooperating; keep mutual cooperation
        return 'C'

    return 'C'
